package io.github.jinyiwei2012.luosandbox.inputcontrol;

import static org.junit.jupiter.api.Assertions.*;
import java.util.*;
import org.junit.jupiter.api.Test;

class InputLeaseTest {
  private static final InputLease.Binding B = new InputLease.Binding("actor", "world", "body", UUID.randomUUID(), 1, UUID.randomUUID(), UUID.randomUUID());
  private static final InputLease.Bounds WALK = new InputLease.Bounds("minecraft:overworld", new InputLease.Position(0, 0, 0), new InputLease.Position(1, 1, 1), 1);
  private static final InputLease.Bounds LOOK = new InputLease.Bounds("minecraft:overworld", new InputLease.Position(0, 0, 0), new InputLease.Position(0, 0, 0), 0);
  private static InputLease.Permit permit(UUID id, String request, InputLease.Intent intent, long requestRemaining) { return new InputLease.Permit(id, B, request, intent, intent == InputLease.Intent.LOOK ? LOOK : WALK, 750, 750, requestRemaining, 750); }
  private static InputLease.TrustedServerContext trusted() { return new InputLease.TrustedServerContext(B, "actual-server-connection"); }
  private static final class Sink implements InputLease.KeySink { Set<InputLease.InputKey> keys = Set.of(); int presses; int releases; boolean failRelease; public void setOwned(Set<InputLease.InputKey> v) { keys = v; presses++; } public void releaseAllOwned() { releases++; if (failRelease) throw new IllegalStateException(); keys = Set.of(); } }
  private static final class Queue implements InputLease.ClientThreadDispatcher { List<Runnable> tasks = new ArrayList<>(); long now; public void dispatch(Runnable r) { tasks.add(r); } public long monotonicNow() { return now; } void run() { List<Runnable> copy = List.copyOf(tasks); tasks.clear(); copy.forEach(Runnable::run); } }
  private static InputLease lease(Sink sink, Queue queue) { return new InputLease(B, sink, queue); }

  @Test void requestDeadlineIsAnExactLeaseCeiling() { Sink s = new Sink(); Queue q = new Queue(); InputLease l = lease(s, q); assertTrue(l.acceptPermit(trusted(), permit(UUID.randomUUID(), "r", InputLease.Intent.BOUNDED_WALK, 50), 0)); assertTrue(l.applyMovement(Set.of(InputLease.InputKey.FORWARD), 1)); q.now = 1; q.run(); assertFalse(l.tick(50)); q.run(); assertTrue(s.keys.isEmpty()); }
  @Test void lookNeverAuthorizesMovement() { Sink s = new Sink(); Queue q = new Queue(); InputLease l = lease(s, q); assertTrue(l.acceptPermit(trusted(), permit(UUID.randomUUID(), "r", InputLease.Intent.LOOK, 100), 0)); assertFalse(l.applyMovement(Set.of(InputLease.InputKey.FORWARD), 1)); q.run(); assertEquals(0, s.presses); assertTrue(s.keys.isEmpty()); }
  @Test void queuedCallbackClockRollbackReleasesAlreadyHeldOwnedKeys() { Sink s = new Sink(); Queue q = new Queue(); InputLease l = lease(s, q); assertTrue(l.acceptPermit(trusted(), permit(UUID.randomUUID(), "r", InputLease.Intent.BOUNDED_WALK, 100), 10)); assertTrue(l.applyMovement(Set.of(InputLease.InputKey.FORWARD), 11)); q.now = 11; q.run(); assertEquals(Set.of(InputLease.InputKey.FORWARD), s.keys); assertTrue(l.applyMovement(Set.of(InputLease.InputKey.FORWARD), 12)); q.now = 10; q.run(); q.run(); assertTrue(s.keys.isEmpty()); }
  @Test void queuedCallbackAtRequestDeadlineReleasesAlreadyHeldOwnedKeys() { Sink s = new Sink(); Queue q = new Queue(); InputLease l = lease(s, q); assertTrue(l.acceptPermit(trusted(), permit(UUID.randomUUID(), "r", InputLease.Intent.BOUNDED_WALK, 50), 0)); assertTrue(l.applyMovement(Set.of(InputLease.InputKey.FORWARD), 1)); q.now = 1; q.run(); assertEquals(Set.of(InputLease.InputKey.FORWARD), s.keys); assertTrue(l.applyMovement(Set.of(InputLease.InputKey.FORWARD), 2)); q.now = 50; q.run(); q.run(); assertTrue(s.keys.isEmpty()); }
  @Test void replayOldPermitAfterRenewalIsRejected() { Sink s = new Sink(); Queue q = new Queue(); InputLease l = lease(s, q); UUID a = UUID.randomUUID(); assertTrue(l.acceptPermit(trusted(), permit(a, "r", InputLease.Intent.BOUNDED_WALK, 100), 0)); assertTrue(l.acceptPermit(trusted(), permit(UUID.randomUUID(), "r", InputLease.Intent.BOUNDED_WALK, 90), 10)); assertFalse(l.acceptPermit(trusted(), permit(a, "r", InputLease.Intent.BOUNDED_WALK, 80), 20)); }
  @Test void rollbackAndQueuedEmergencyFailClosed() { Sink s = new Sink(); Queue q = new Queue(); InputLease l = lease(s, q); assertTrue(l.acceptPermit(trusted(), permit(UUID.randomUUID(), "r", InputLease.Intent.BOUNDED_WALK, 100), 10)); assertTrue(l.applyMovement(Set.of(InputLease.InputKey.FORWARD), 11)); l.emergencyStop(B); q.now = 12; q.run(); assertTrue(s.keys.isEmpty()); assertFalse(l.tick(9)); }
  @Test void trustedHigherEpochOnlyResetsFenceAndBoundsAreStrict() { Sink s = new Sink(); Queue q = new Queue(); InputLease l = lease(s, q); l.emergencyStop(B); assertFalse(l.advanceBinding(new InputLease.HigherEpochProof(B, "same"))); InputLease.Binding next = new InputLease.Binding("actor", "world", "body", UUID.randomUUID(), 2, UUID.randomUUID(), UUID.randomUUID()); assertTrue(l.advanceBinding(new InputLease.HigherEpochProof(next, "proof"))); assertThrows(IllegalArgumentException.class, () -> new InputLease.Bounds("d", new InputLease.Position(2, 0, 0), new InputLease.Position(1, 0, 0), 1)); }
  @Test void releaseFailureLeavesLeaseDenied() { Sink s = new Sink(); Queue q = new Queue(); InputLease l = lease(s, q); s.failRelease = true; l.shutdown(); q.run(); assertFalse(l.acceptPermit(trusted(), permit(UUID.randomUUID(), "r", InputLease.Intent.BOUNDED_WALK, 10), 1)); }
}
